import json,pathlib,hashlib,re
ROOT=pathlib.Path(__file__).resolve().parents[5];OUT=pathlib.Path(__file__).resolve().parent
SHARD='cooking-service2';DOCS=['rst-2-cooking','rst-2-service'];BASE='8a0ebfe5f799847ac1fd590a3b610cb0837f7667'
lessons=json.loads((ROOT/'src/data/restaurant/lessons.2.ja.json').read_text())['lessons'];by={l['id']:l for l in lessons};ledger=json.loads((ROOT/'docs/ssw-workspace/restaurant/knowledge-ledger.json').read_text())['units'];assigned=[u for u in ledger if any(u['id'].startswith(d+'-') for d in DOCS)];facts=[];additions=[];questions=[];figures=[]
def units(doc,numbers):return [doc+'-'+('k'+x.zfill(3) if x.isdigit() else x) for x in numbers.split()]
def refs(doc,pages,section):return [{'documentId':doc,'pdfPages':pages,'section':section}]
def add(tag,lesson,title,text,unitnums,pages,doc='rst-2-cooking'):
 additions.append({'id':'rst31-cs2-'+tag,'lessonId':lesson,'titleJa':title,'textJa':text,'unitIds':units(doc,unitnums),'factIds':[],'sourceRefs':refs(doc,pages,title)})
def fact(tag,doc,nums,text,pages,lesson=None,paragraph=None,qs=None,addition=None,visual=None,field=None,path=None,reason=None):
 fid='rst31-cs2-f-'+tag;ev=[]
 if lesson and paragraph:
  assert any(p['id']==paragraph for p in by[lesson]['paragraphs']);ev.append({'kind':'lesson_paragraph','lessonId':lesson,'paragraphId':paragraph,'path':'src/data/restaurant/lessons.2.ja.json','field':f'lessons/{lesson}/paragraphs/{paragraph}/textJa','reason':reason or '該当段落を実読し、この事実の条件と意味が教えられていることを確認。'})
 if path:ev.append({'kind':'guide_or_glossary','path':path,'field':field,'reason':reason or '該当する日本語データと表示側の対象条件を実読し、この事実に対応すると確認。'})
 for q in qs or []:ev.append({'kind':'existing_question','questionId':q,'path':'src/data/restaurant/exams.2.ja.json','field':'questions/'+q,'reason':'設問と正答がこの個別能力を直接確認する。'})
 aids=['rst31-cs2-'+addition] if addition else [];f={'id':fid,'unitIds':units(doc,nums),'statementJa':text,'sourceRefs':refs(doc,pages,text[:38]),'existingEvidence':ev,'additionIds':aids,'questionIds':qs or [],'visualEvidence':visual or [],'decision':'covered_after_additions' if addition else 'covered_existing'};facts.append(f)
 for a in additions:
  if a['id'] in aids:a['factIds'].append(fid)
 return fid
C='rst-2-cooking';S='rst-2-service'
add('meat-quality','rst-2-cook-01','肉の変化と種類別の品質観察','牛肉は部位ごとの食感の違いが大きい。豚肉は比較的均一と説明されるが、脂の多いばら等は区別する。肉は、と畜後の硬直から熟成・軟化へと状態が変わる。筋切り、肉たたき、しょうが汁等を使う処理も目的と料理の仕様で選ぶ。日数だけを根拠に厨房で常温熟成させず、仕入れ規格と保管管理に従う。加熱によるタンパク質の変性で収縮や肉汁の流出が起こり、筋の多い部位ではコラーゲンの変化も食感に関わる。教材の約60℃は変性の説明で、食中毒を防ぐ加熱条件ではない。品質の観察例は、牛では赤身と脂の境界、豚では淡い桃色のつやと白い脂、鶏では透明感のある桃色と皮の毛穴の凹凸である。いずれも、異臭、汁の流出、弾力、ぬめりを併せて見て、見た目を安全の保証にしない。','002 004',[5,6])
add('fish-quality','rst-2-cook-01','魚介類の観察と加工後の向き','魚介類の旬は、教材では脂ののった時期を説明する言葉であり、生食の安全認定ではない。丸魚は目の澄み方とくぼみ、えらの色、腹の弾力、体の張りとつや、異臭、うろこの状態を、切り身は弾力・つや・切り口を確認する。教材では肉より魚介、小魚や貝は特に劣化しやすいと説明し、温度変動を抑える保管を求めている。三枚おろしは左右の身二つと中骨、五枚おろしは平たい魚などの身四つと中骨へ分ける。盛り付けの教材例では丸魚の頭を左・腹を下にし、和食の付け合わせを手前へ置く。切り身は身を手前、皮を奥にし、洋食の付け合わせは奥へ置く。自店の盛付基準と照合してから提供する。','005',[6,7])
add('fish-preparation','rst-2-cook-03','丸魚の下処理で方向と位置を確かめる','実演を受けた手順で、魚を安定させて作業する。うろこは尾から頭へ向かって落とし、専用具、又は包丁の背を使う場合も身を傷めない当て方を確認する。えらは腹側を上にしてえらぶたを開き、えらと身がつながる部分を両側から外して取り出す。内臓を除く切り込みは用途で異なる。切り身用はえら付近から腹へ開き、尾頭付きは表に切り込みを見せないため裏側の胸びれ下から処理する。処理後は流水で手早く洗い、水分を十分に除く。頭を外す時は腹びれの後方の付け根から胸びれの後方へ斜めに中骨まで入れ、反対側も処理して頭を外す。位置を示す図は実物指導の代わりではなく、未訓練者が図だけで刃物操作を始めない。','014 015 016 017 018 019',[9,10])
add('nonheat-thaw','rst-2-cook-04','非加熱の衛生確認と解凍条件','後で加熱しない和え物では、手を洗ってから使い捨て手袋を着け、菜箸やトングを使う時も洗浄済みか確かめる。ボウルは作業の都度清潔なものを用い、完成後の保管は覆いと冷蔵条件を管理する。生食用の冷凍魚は、組織や汁の流出にも配慮して指定された低温の解凍条件に従う。一方、衣付きの半製品などには凍結状態から加熱する製品がある。冷凍野菜を含め、加熱が必要か、解凍のみで食べられるかを製品表示で確かめる。古い教材の「冷凍野菜に生食用はない」という一律の記述や、ブランチングの温度例だけから、現物の食べ方を決めない。','022',[10,11])
add('heat-equipment','rst-2-cook-05','熱機器の点検は設定値と実際を分ける','自動温度調節でも設定値だけで済ませず、適切な計器で実際の状態を確認する。ガス機器は換気とバーナー周りの汚れを点検し、着火不良や途中消火を放置しない。蒸気を使うオーブンは高温蒸気を避ける開閉方法を守り、清掃前の冷却・停止と自動洗浄の指定条件を確認する。2023年版教材には揚げ油のAV値3.0を区切りとする交換例があるが、酸価を表すAVを油の安全性全体や法令共通の合否値と混同しない。現場では製品、機器、自店の衛生管理計画の交換基準を確認し、異常な油で営業を続けない。','025 026',[11,12])
add('other-heat-equipment','rst-2-cook-05','熱機器ごとの観察対象を指示する','蒸し器は各部で蒸気が正常に上がるか、ゆで麺器は湯の状態と指定温度を確かめる。教材のほぼ100℃は例であり、全機種・全条件を同じ温度で運転する指示ではない。グリドルやブレージングパンは端と中央を測って温度むらを調べる。教材の10℃以上という差の例を学んだうえで、調整権限と機器の基準に従う。炊飯器は炊き上がりの品質、焼き物器は焼きかすと火力むら、ジェットオーブンはベルトの汚れと仕上がり、回転釜は完成状態を確認する。腐敗や薬剤混入が疑われる品を味見して確かめず、提供を止めて原因を調べる。','025 026',[12])
add('washer-cold','rst-2-cook-05','洗浄機と冷機器の見落としを防ぐ','洗浄機はノズルの詰まりだけでなく、排水部の漏れ、作業台とラック、給湯、洗剤の補充も確認する。教材の洗浄60～70℃、すすぎ80～90℃は記載された運転例であり、全機種の合否基準ではない。自店の機器と薬剤の指示に照らし、洗浄・すすぎを取り違えない。冷機器ではパッキンの破損やかび、冷却部の油とほこり、外せる棚や背面の食品かす、製氷部のごみや虫を点検する。氷用スコップは氷や製氷皿の中へ放置せず、外の衛生的な指定場所へ保管する。','025 027 028',[12,13])
add('eight-knives','rst-2-cook-06','八つの包丁の用途を比べる','柳刃は長い刃で刺身を切り、出刃は厚みと重みがあり魚の処理に用いる。野菜用の菜切は刻みや千切り、薄刃は皮むきや細工などの用途を比べる。牛刀は肉に限らず魚や野菜にも用い、三徳も肉・魚・野菜へ広く使う。小型のペティは皮むきなど細かい作業、中華包丁は広い刃と重みを生かす作業に用いる。名称が似る物でも、硬い骨を薄い刃で切るなど用途を外した使い方はしない。鋼の包丁は洗浄後の水分を除き、アルコール使用後も残る水分の扱いを確認する。薬剤の必要な作用時間を勝手に短くせず、製品の指示と両立した乾燥手順を守る。','029',[13,14])
add('containers-pans','rst-2-cook-06','容器の隅と鍋の材質を分けて手入れする','キッチンポット、ホテルパン、角盆、ボウルは、スポンジなど適した用具で洗い、隅の汚れも調べる。金属たわしの破片や傷を残す方法は避け、汚れが残れば洗い直して指定の消毒を行う。フッ素加工面は柔らかいスポンジと適合する洗剤で扱い、熱い状態から急冷しない。鉄のフライパンは水気を取り、説明書に適合する乾燥加熱と油の手入れをする。鍋の材料には鉄、ステンレス、アルミニウム、アルマイト、銅、ガラス、陶磁器があり、形・厚さ・深さ、耐久性と熱源への適合で選ぶ。全素材に同じたわしや加熱を当てはめない。','029',[14])
add('historical-accidents','rst-2-cook-07','年代を固定して災害の構成を読む','2023年版教材が引用する令和4年の図では、転倒30％、切れ・こすれ20％、高温・低温物との接触15％、動作の反動・無理な動作10％、墜落・転落6％、激突5％、交通事故4％、はさまれ・巻き込まれ4％、その他6％と示される。上位三つを優先して観察する練習に使うが、現在の発生割合や一店舗の事故率へ置き換えない。安全活動では整理・整頓・清掃・清潔・習慣の5Sを、通路の物や水・油の除去、所定位置への収納、状態の維持と繰返し確認へ結び付ける。','032 033 035',[15,18])
add('hazard-scenes','rst-2-cook-07','危険を場所と動作で見えるようにする','転倒は濡れた床だけでなくグレーチングや暗い通路、視界をふさぐ荷物も確認する。切傷は包丁、シンク内の刃物、缶のふち、割れた食器、串を含むごみで起こり得る。冷凍品は滑りや転がりを防ぐ手順を確かめ、洗浄やごみの取扱いには作業に合う保護具を用いる。やけどは鍋や揚げ油に触れる場面、熱い物を持った同僚との接触、濡れた床での転倒でも起こる。抽出後のコーヒーフィルターにも熱湯が残ることがある。重い物は体から離して無理に持たず、台車や分割・複数人運搬を使う。写真や図の警告を実際の安全手順、配置、訓練へ結び付け、暑熱への対策も確認する。','034 035',[15,16,17,18])
add('machine-guards','rst-2-cook-07','食品加工機械は危険部と作業を区別する','切断・切削機は加工に必要な部分以外の刃へ覆い等を設け、危険がある投入・取出しは停止や指定の用具などで手が届かない方法を守る。粉砕・混合機では開口部への転落と内部への接触を防ぐ蓋等が必要になる。ロール機は巻き込まれる部分、成形・圧縮機は挟まれ・巻き込まれる部分の覆い等を確認する。蓋やカバーを無効にして続けない。掃除、給油、検査、調整、詰まりの除去などで危険がある時は、原則として停止し、再始動を防ぐ手順を守る。具体的な構造・法令上の適用条件は現行資料と機械の説明書で確認し、図だけで例外を判断しない。','035',[18,19])
add('allergy-update','rst-2-svc-05','教材の八品目と現在の表示制度を区別する','2023年版教材は、卵・乳・小麦・そば・落花生・えび・かに・くるみの八品目を当時の特定原材料として挙げている。消費者庁の2026年4月1日改正ではカシューナッツが特定原材料へ追加され、九品目となった。経過措置中は、表示だけから含まれないと決めつけない。食品表示制度の対象と、飲食店が個別に行う情報提供を混同せず、材料、調味料、共用器具やゆで湯まで調べる。仕入れや配合が変わった時は、メニューや掲示、担当者の案内も更新し、未確認の完全除去を約束しない。','026',[12,13],S)
add('taste-complaint','rst-2-svc-05','味の申し出を安全確認と品質改善へ分ける','味がおかしいとの申し出は、単なる好みの違いと決めつけない。腐敗、異物、薬剤の混入などが疑われる時は、自分が味見して安全を確かめようとせず、その品の提供を止め、原料、作業工程、保管履歴と客の状態を確認して責任者へつなぐ。通常の品質確認を安全に行える場面でも、自店の方法で味や分量、工程を照合する。問題を直すだけで終わらせず、原因と変更点を担当者全員へ共有し、次の仕込みや提供で改善を確かめる。','029',[14],S)
add('workday-timeline','rst-2-svc-06','開店から引継ぎまでの仕事をつなぐ','開店前は空調を早めに整え、調理機器の立上げ時間、照明・音楽、出勤者と身だしなみを確認する。資料の30分前という機器起動は一つの例であり、自店の機器で所要時間を決める。図の一日例には、サービスルームの照明・コンセント、保温器、食器やカップ、冷水、メニューの準備、店頭や客席、冷暖房、トイレの点検がある。営業中は釣銭、飲料材料、備品の補充と汚れた部分の清掃を行い、中間の点検、発注、不要機器の停止、夕方への準備と引継ぎへつなぐ。閉店前の清掃・補充・棚卸しを接客と両立させ、次の担当への連絡を記録する。最終確認では食品、売上金、火気・水道・ガス、機器、入口と防犯を担当と照合する。図の時刻・釣銭額は特定店舗の例で、自店の約束や安全手順には転用しない。','032 033 034',[14,15,16],S)
add('mop-window','rst-2-svc-09','モップの移動とガラスの水切りを実演する','モップは糸を広げ、重なる8の字を描いて後ろへ下がりながら拭く。人が入らない作業範囲と退路を確保し、隅と両端を先に、中央を後で仕上げる方法を練習する。大きな窓の教材例は、適合する洗剤を準備してガラス全体を濡らし、スクイジーで水を切る。水を切るたびに用具の刃先をクロスで拭き、最後に窓枠も乾かす。小さな窓や鏡、電気機器の周りは、素材と指定方法に適合するクロスを用いる。薬剤の倍率、噴霧距離、清掃頻度は教材例を全製品へ広げず、現物の説明書で確認する。','035 036 visual018',[17,18],S)
add('cleaning-zones','rst-2-svc-09','場所別の用具と清掃の終点を決める','外周はほうきとちり取りでごみを集めて回収し、ごみかごの量も点検する。植え込みはごみを除き、植物や季節に適した散水を確認し、灯具の汚れも扱う。床はワックス塗布の有無を区別する。非塗布の入口床などはごみを除いて適合する洗浄を行い、モップをよく絞って隅と中央を拭く。ワックス塗布床は掃除機などで砂を除き、指定された用具・方法で仕上げる。カーペットのしみは材質と薬剤に合う方法で処理し、家具のワックスは対応素材と放置・乾燥条件が確認できる場合だけ使う。電話やレジは液を直接吹き込まず、適合するクロスへ付けて拭く方法を確認する。','035 036 visual018 visual019',[18,19],S)
add('condiments-toilets','rst-2-svc-09','容器の再充填とトイレ清掃を混ぜない','調味料容器は内容物を店の手順で扱って空にし、容器を洗い、流水ですすぎ、逆さにするなどして十分に水を切ってから再充填する。汚れた容器へ継ぎ足して完了にしない。化粧室は壁、洗面台、ドア外側、床、便器の内外で用具と汚染区分を分ける。便器は専用ブラシで内部を洗い流し、外側は指定のクロスで扱う。客席用クロスや調味料容器用スポンジを流用しない。教材の毎日三回以上などの頻度は一例で、利用状況と自店の計画で巡回し、作業後の用具の洗浄・乾燥と手洗いまで確認する。','035 036 visual019',[19],S)
add('complaint-report-items','rst-2-svc-08','責任者への報告を四つに分ける','申し出の内容、確認できた原因や事実、既に行った処置、近くの席など周囲の状況を整理して責任者へ渡す。相手の話は途中で反論せず最後まで聞き、分からない原因を断定しない。責任者は改めてお詫びし、事情と対応案を説明して希望を確かめる。人・場所・時機を変える時も、安全と本人の意向を尊重する。最後に申し出への謝意を伝え、対応と原因対策を日報等で本部へ報告し、他の担当や店舗でも同じ問題を防げるよう共有する。','041 042 043 visual021',[20,21,22],S)
add('illness-training','rst-2-svc-08','体調急変では連絡と応急手当を分担する','周囲の安全を確かめ、本人が話せる場合は症状や希望を聞き、同伴者からも必要な情報を受ける。ただし、反応がない、普段どおりの呼吸がない・判断に迷う、重い症状がある時は、同伴者の到着や許可を待って救急要請を遅らせない。119番通報、AEDの手配、入口からの誘導、他の客の安全確保を分担する。心停止が疑われる場面は通信指令員の指示と受けた救命講習に従い、胸骨圧迫とAEDの準備を進める。けいれんで倒れた場合も、周囲の危険を避けて救急へ状況を伝え、医療的な判断を独断で行わない。AEDの場所と使い方、通報と引継ぎは全時間帯の担当者で定期的に訓練する。','048 049',[22,23],S)
add('emergency-links','rst-2-svc-08','緊急時の行動基準を店舗運営と照合する','接客側の初動は、店舗運営で定めた緊急時の担当表とつなげる。発見した人が危険を知らせ、責任者は通報、避難誘導、救急隊の案内、厨房や本部への連絡を割り当てる。復旧や営業再開は接客担当の独断で決めず、原因と安全の確認、関係先の判断、実施した処置の報告をそろえる。訓練では「誰が通報するか」「どの出口へ誘導するか」「誰へ状況を渡すか」を自店の計画で回答し、未確認の担当や連絡先を残さない。','050',[23],S)
add('kitchen-term-detail','rst-2-cook-12','厨房用語を数量と設備の判断へ戻す','検品では品名・数量だけでなく単価、銘柄、鮮度や熟成、破損と欠品も発注条件と比べる。キッチンレイアウトはメニュー、原料の加工度、調理システム、要員、販売予測から機器を選び、温度区分と動線を組み立てる。セントラルキッチンの集中加工は味の均一化や費用低減をねらい、仕様書発注は自社の加工場がなくても外部へ条件を伝える方法になる。在庫は数量だけでなく金額も占め、長期保管は品質にも影響する。棚卸しは実物から数量と金額を確かめる作業として、記録上の残高と混同しない。','ref01',[22,23])
add('service-term-detail','rst-2-svc-10','サービス用語を改善の指標として使う','クレンリネスは乾燥、清潔で美しい仕上がり、整理整頓を継続する考え方として実践する。CSはアンケートや聞き取り等で確かめる顧客満足で、店側の自己評価だけではない。主力商品は人気だけでなく粗利益への貢献という見方もあり、フェアには販売促進のほか新商品の反応を見る役割がある。客席レイアウトは人数に合う席と通路を、サービスステーションは新規客の把握、卓上準備や中間下げの中継を考えて設計する。数値や名称を並べるだけでなく、何を観察し、どの行動を変えるかまで記録する。','ref01',[24,25],S)
additions=[a for a in additions if a['id']!='rst31-cs2-emergency-links']
add('heat-transfer-detail','rst-2-cook-04','加熱の媒体と油の変化を分ける','ゆでる時は水や湯、煮る時は調味した煮汁、蒸す時は水蒸気という媒体を区別する。揚げ物では多量の高温油を使い、食品から水分が失われ油を吸収するため、投入量と仕上がりも確認する。少量の油で混ぜる炒め物と同じ工程にはしない。料理の厚さや機器条件に合う加熱を守り、表面の焼き色だけで内部の安全を判断しない。','021',[10])
